window.docContents[182].resolve({"/rules/PL1004/#PL1004-example":{"contents":"\n\nThe correction proves the same concrete equality (2 : Nat) = 2 by rfl. The violation reports both the generated axiom and its parent theorem.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL1004: Compiler-trusting proofs require separate classification","header":"Checked example","id":"/rules/PL1004/#PL1004-example"},"/rules/PL2003/#PL2003-example":{"contents":"\n\nThe correction removes a dead lambda binding while preserving identity's complete natural-number behavior. No warning or linter is disabled.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL2003: Claimed source must elaborate warning-free","header":"Checked example","id":"/rules/PL2003/#PL2003-example"},"/rules/PL3002/#PL3002-example":{"contents":"\n\nThe correction adds the missing equality between the reference and its replacement on the full natural-number domain, keeping the checked execution claim and both implementations.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL3002: Checked execution requires admitted correspondence","header":"Checked example","id":"/rules/PL3002/#PL3002-example"},"/rules/PL4001/#PL4001-example":{"contents":"\n\nThe correction removes the orphan marker; the positive reflexivity fence is unchanged.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL4001: Documentation fences must have a valid classification","header":"Checked example","id":"/rules/PL4001/#PL4001-example"}});